# 하이퍼파라미터 튜닝 예시: Python 3에서 실행 가능한 코드
candidates = {"lr": [0.1, 0.01], "depth": [3, 4]}
for lr in candidates["lr"]:
    for depth in candidates["depth"]:
        print(lr, depth)

# 그리드 서치 예시: Python 3에서 실행 가능한 코드
for lr in [0.1, 0.01]:
    for batch in [16, 32]:
        print({"lr": lr, "batch": batch})

# 특징 중요도 예시: Python 3에서 실행 가능한 코드
importance = {"age": 0.2, "income": 0.6, "city": 0.2}
print(max(importance, key=importance.get))

# t-SNE 예시: Python 3에서 실행 가능한 코드
neighbors = {"A": ["B", "C"], "D": ["E"]}
print(len(neighbors["A"]))

# UMAP 예시: Python 3에서 실행 가능한 코드
embedding = {"sample1": (0.1, 0.5), "sample2": (0.2, 0.55)}
print(embedding["sample1"])

# 하이브리드 추천 예시: Python 3에서 실행 가능한 코드
collab = {"A": 0.7}
content = {"A": 0.9}
score = 0.6 * collab["A"] + 0.4 * content["A"]
print(score)

# 아이템 기반 협업 필터링 예시: Python 3에서 실행 가능한 코드
liked = {"사용자": {"책A", "책B"}}
similar_items = {"책A": ["책C"]}
print(similar_items["책A"][0])

# 콘텐츠 기반 필터링 예시: Python 3에서 실행 가능한 코드
profile = {"sf", "space"}
movie = {"sf", "robot"}
score = len(profile & movie)
print(score)

# 클래스 가중치 예시: Python 3에서 실행 가능한 코드
counts = {"major": 90, "minor": 10}
weights = {k: 100 / v for k, v in counts.items()}
print(weights)

# 다중 레이블 분류 예시: Python 3에서 실행 가능한 코드
labels = {"movie1": ["action", "comedy"]}
print("comedy" in labels["movie1"])
